const quotePremium = (step: QuoteStep, context: PolicyContext): number => {
  const basePremium = policyBasePremium(step.items);
  return Math.ceil(
    basePremium +
      percentOf(basePremium, applicablePercent(POLICY_MODIFIER_RULES, context)) +
      totalItemSurcharges(step.items) +
      PROCESSING_FEE,
  );
};

const runStep = (step: Step, context: PolicyContext): StepResult => {
  if (step.op === "quote") return { premium: quotePremium(step, context) };
  throw new Error(`Unsupported step: ${step.op}`);
};

const countQuotes = (steps: Step[]): number =>
  steps.filter((step) => step.op === "quote").length;

export const runScenario = (scenario: Scenario): ScenarioResult => ({
  results: scenario.steps.map((step, index) =>
    runStep(step, {
      customer: scenario.customer,
      precedingQuoteCount: countQuotes(scenario.steps.slice(0, index)),
    }),
  ),
});
